package com.atmaca.tasiyici;
import android.app.*;import android.os.*;import android.content.*;import android.net.Uri;import android.provider.Settings;import android.graphics.Color;import android.view.*;import android.widget.*;import java.io.*;import java.util.*;
public class MainActivity extends Activity {
 TextView status; Button start; volatile boolean busy=false; File dest;
 public void onCreate(Bundle b){super.onCreate(b);LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setPadding(30,50,30,20);l.setBackgroundColor(Color.rgb(255,249,225));TextView title=new TextView(this);title.setText("ATMACA 1907 • Görsel Klasör Taşıyıcı");title.setTextSize(22);title.setTextColor(Color.rgb(10,35,110));l.addView(title);status=new TextView(this);status.setText("\nGörsel içeren klasörleri DCIM/1907 içine TAŞIR. Kopyalama yapmaz.\n\nÖnce dosya erişim izni verin.\n");l.addView(status);start=new Button(this);start.setText("İZİN VER / KLASÖRLERİ TARA");l.addView(start);setContentView(l);start.setOnClickListener(v->begin());}
 void say(String s){runOnUiThread(()->status.setText(s));}
 void begin(){if(busy)return;if(!Environment.isExternalStorageManager()){Intent i=new Intent(Settings.ACTION_MANAGE_APP_ALL_FILES_ACCESS_PERMISSION,Uri.parse("package:"+getPackageName()));startActivity(i);return;} File root=Environment.getExternalStorageDirectory();dest=new File(root,"DCIM/1907");busy=true;start.setEnabled(false);say("Klasörler taranıyor...");new Thread(()->{ArrayList<File> matches=new ArrayList<>();scan(root,matches,0);runOnUiThread(()->{busy=false;start.setEnabled(true);if(matches.isEmpty()){say("Taşınacak görsel klasörü bulunamadı.");return;}new AlertDialog.Builder(this).setTitle("Taşıma onayı").setMessage(matches.size()+" klasör DCIM/1907 içine taşınacak. İşlem öncesi yedek önerilir. Devam edilsin mi?").setNegativeButton("İptal",null).setPositiveButton("TAŞI",(d,w)->move(matches)).show();});}).start();}
 boolean image(String n){String s=n.toLowerCase(Locale.ROOT);return s.endsWith(".jpg")||s.endsWith(".jpeg")||s.endsWith(".png")||s.endsWith(".webp")||s.endsWith(".gif")||s.endsWith(".heic")||s.endsWith(".heif")||s.endsWith(".bmp")||s.endsWith(".avif");}
 void scan(File dir,ArrayList<File> out,int depth){if(depth>40||out.size()>200000||dir.equals(dest)||dir.getAbsolutePath().startsWith(dest.getAbsolutePath()+"/"))return;File[] fs=dir.listFiles();if(fs==null)return;boolean has=false;for(File f:fs)if(f.isFile()&&image(f.getName())){has=true;break;}if(has&&!dir.equals(Environment.getExternalStorageDirectory())&&!dir.getName().equalsIgnoreCase("DCIM")){out.add(dir);return;}for(File f:fs)if(f.isDirectory()&&!f.getName().equals("Android")&&!f.getName().startsWith("."))scan(f,out,depth+1);}
 void move(ArrayList<File> dirs){busy=true;start.setEnabled(false);new Thread(()->{if(!dest.exists()&&!dest.mkdirs()){say("Hedef klasör oluşturulamadı.");finishJob();return;}int ok=0,fail=0;for(File src:dirs){if(src.equals(dest)||src.getAbsolutePath().startsWith(dest.getAbsolutePath()+"/"))continue;File target=new File(dest,src.getName());int n=1;while(target.exists())target=new File(dest,src.getName()+"_"+(n++));if(src.renameTo(target))ok++;else fail++;final int a=ok,b=fail;say("Taşınan: "+a+" | Taşınamayan: "+b+" / "+dirs.size());}say("İşlem tamamlandı. Taşınan: "+ok+"\nTaşınamayan (yerinde bırakıldı): "+fail+"\nHedef: DCIM/1907");finishJob();}).start();}
 void finishJob(){runOnUiThread(()->{busy=false;start.setEnabled(true);});}
}
